import { test } from 'node:test'
import assert from 'node:assert/strict'

import { inlineSvg } from './svg-inline.js'

/** draw.io の実 export を模した最小 SVG（構造は実出力に合わせている）。 */
const svgOf = ({ width = 412, height = 131, extra = '', body = '' } = {}) => `<?xml version="1.0" encoding="UTF-8"?>
<!-- Do not edit this file with editors other than draw.io -->
<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN" "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">
<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" style="background: transparent;" version="1.1" width="${width}px" height="${height}px" viewBox="0 0 ${width} ${height}"${extra}>
  <g>${body}</g>
</svg>`

test('width/height を外し viewBox を残す', () => {
  // 子要素の width/height は残って当然なので、root の svg タグだけを見る
  const { svg } = inlineSvg(svgOf({ body: '<rect width="10" height="10"/>' }), { idPrefix: 'fig1' })
  const rootTag = svg.slice(0, svg.indexOf('>') + 1)
  assert.ok(!/\swidth="/.test(rootTag), 'root の width が残っている')
  assert.ok(!/\sheight="/.test(rootTag), 'root の height が残っている')
  assert.match(svg, /viewBox="0 0 412 131"/)
  assert.match(svg, /<rect width="10"/, '子要素の寸法まで消している')
})

test('本文幅に追随するよう max-width を足す', () => {
  const { svg } = inlineSvg(svgOf(), { idPrefix: 'fig1' })
  assert.match(svg, /max-width:\s*100%/)
  assert.match(svg, /height:\s*auto/)
})

test('XML 宣言・DOCTYPE・コメントを落とす', () => {
  const { svg } = inlineSvg(svgOf(), { idPrefix: 'fig1' })
  assert.ok(!svg.includes('<?xml'), 'XML 宣言が残っている')
  assert.ok(!svg.includes('<!DOCTYPE'), 'DOCTYPE が残っている')
  assert.ok(!svg.includes('<!--'), 'コメントが残っている')
  assert.ok(svg.startsWith('<svg'), 'svg 要素で始まっていない')
})

test('id に接頭辞を付けて衝突を防ぐ', () => {
  const { svg } = inlineSvg(svgOf({ body: '<rect id="box"/>' }), { idPrefix: 'fig1' })
  assert.match(svg, /id="fig1-box"/)
  assert.ok(!/id="box"/.test(svg), '元の id が残っている')
})

test('id を指す url(#...) 参照も追随させる', () => {
  const body = '<defs><marker id="arrow"/></defs><path marker-end="url(#arrow)"/>'
  const { svg } = inlineSvg(svgOf({ body }), { idPrefix: 'fig1' })
  assert.match(svg, /id="fig1-arrow"/)
  assert.match(svg, /marker-end="url\(#fig1-arrow\)"/)
})

test('フラグメント参照 href="#..." も追随させる', () => {
  const body = '<defs><path id="p1"/></defs><use xlink:href="#p1"/>'
  const { svg } = inlineSvg(svgOf({ body }), { idPrefix: 'fig1' })
  assert.match(svg, /href="#fig1-p1"/)
})

test('外部 URL は書き換えない', () => {
  const body = '<a xlink:href="https://example.com/#p1"><rect id="p1"/></a>'
  const { svg } = inlineSvg(svgOf({ body }), { idPrefix: 'fig1' })
  assert.match(svg, /href="https:\/\/example\.com\/#p1"/)
})

test('id-prefix 未指定なら衝突リスクを警告する', () => {
  const { warnings } = inlineSvg(svgOf())
  assert.ok(warnings.some((w) => w.includes('id が衝突')))
})

test('viewBox 幅が本文幅の目安を超えたら警告する', () => {
  const { warnings } = inlineSvg(svgOf({ width: 1200 }), { idPrefix: 'fig1' })
  assert.ok(warnings.some((w) => w.includes('1200') && w.includes('780')))
})

test('viewBox 幅が目安内なら警告しない', () => {
  const { warnings } = inlineSvg(svgOf({ width: 700 }), { idPrefix: 'fig1' })
  assert.deepEqual(warnings, [])
})

test('日本語があれば font-family に日本語フォントを足す', () => {
  const body = '<g style="font-family: Helvetica; font-size: 12px;"><text>ユーザー</text></g>'
  const { svg } = inlineSvg(svgOf({ body }), { idPrefix: 'fig1' })
  assert.match(svg, /font-family: Helvetica, 'Hiragino Sans'/)
})

test('font-family 属性形式にも足す', () => {
  const body = '<text font-family="Helvetica">日本語</text>'
  const { svg } = inlineSvg(svgOf({ body }), { idPrefix: 'fig1' })
  assert.match(svg, /font-family="Helvetica, 'Hiragino Sans'/)
})

test('日本語が無ければフォントに触らない', () => {
  const body = '<g style="font-family: Helvetica;"><text>ASCII only</text></g>'
  const { svg } = inlineSvg(svgOf({ body }), { idPrefix: 'fig1' })
  assert.match(svg, /font-family: Helvetica;/)
  assert.ok(!svg.includes('Hiragino'), '不要なフォールバックを入れている')
})

test('--no-font-fallback で注入を止められる', () => {
  const body = '<g style="font-family: Helvetica;"><text>日本語</text></g>'
  const { svg } = inlineSvg(svgOf({ body }), { idPrefix: 'fig1', fontFallback: false })
  assert.ok(!svg.includes('Hiragino'))
})

test('既に日本語フォントがあれば二重に足さない', () => {
  const body = "<g style=\"font-family: 'Yu Gothic';\"><text>日本語</text></g>"
  const { svg } = inlineSvg(svgOf({ body }), { idPrefix: 'fig1' })
  assert.ok(!svg.includes('Hiragino'))
})

test('埋め込まれた編集用の原本（content 属性）を壊さない', () => {
  const content = ' content="&lt;mxfile&gt;&lt;diagram id=&quot;p1&quot;&gt;&lt;/diagram&gt;&lt;/mxfile&gt;"'
  const { svg } = inlineSvg(svgOf({ extra: content, body: '<rect id="p1"/>' }), { idPrefix: 'fig1' })
  assert.match(svg, /content="[^"]*id=&quot;p1&quot;/, '原本の id まで書き換えている')
  assert.match(svg, /<rect id="fig1-p1"/, '表示要素の id が付け替わっていない')
})

test('viewBox が無ければ width/height を残して警告する', () => {
  const noViewBox = '<svg xmlns="http://www.w3.org/2000/svg" width="100px" height="50px"><g/></svg>'
  const { svg, warnings } = inlineSvg(noViewBox, { idPrefix: 'fig1' })
  assert.match(svg, /width="100px"/)
  assert.ok(warnings.some((w) => w.includes('viewBox')))
})

test('既にフォールバックがある指定では警告を出さない', () => {
  // Mermaid 変換の出力は "Trebuchet MS, Verdana, Arial, sans-serif" のように
  // sans-serif で終わる。注入不要なだけで異常ではないので警告してはいけない
  const body = `<g style="font-family: 'Trebuchet MS', Verdana, Arial, sans-serif;"><text>日本語</text></g>`
  const { warnings } = inlineSvg(svgOf({ body }), { idPrefix: 'fig1' })
  assert.deepEqual(warnings, [])
})

test('font-family の指定が本当に無いときは警告する', () => {
  const { warnings } = inlineSvg(svgOf({ body: '<text>日本語</text>' }), { idPrefix: 'fig1' })
  assert.ok(warnings.some((w) => w.includes('font-family')))
})

test('色をライト固定にして白背景で線が消えるのを防ぐ', () => {
  // draw.io は color-scheme: light dark を書き出すため、閲覧側がダークだと
  // light-dark(#000000, #ffffff) が白を選び、白背景の文書で線が消える
  const dark = svgOf({ extra: '', body: '<path stroke="light-dark(#000000, #ffffff)"/>' })
    .replace('style="background: transparent;"', 'style="background: transparent; color-scheme: light dark;"')
  const { svg } = inlineSvg(dark, { idPrefix: 'fig1' })
  assert.match(svg, /color-scheme: light[;"]/)
  assert.ok(!/color-scheme: light dark/.test(svg), 'ダーク追随が残っている')
})

test('color-scheme が無い SVG にもライト固定を足す', () => {
  const { svg } = inlineSvg(svgOf(), { idPrefix: 'fig1' })
  assert.match(svg, /color-scheme: light/)
})

test('--color-scheme auto なら draw.io の指定をそのまま残す', () => {
  const dark = svgOf().replace('style="background: transparent;"', 'style="color-scheme: light dark;"')
  const { svg } = inlineSvg(dark, { idPrefix: 'fig1', colorScheme: 'auto' })
  assert.match(svg, /color-scheme: light dark/)
})

test('SVG でないものは例外にする', () => {
  assert.throws(() => inlineSvg('<html><body/></html>'), /SVG のルート要素/)
})
